function period(day,kind){date(day);const d=new Date(day+'T12:00:00Z');let start=new Date(d),end=new Date(d);if(kind==='semana'){start.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));end=new Date(start);end.setUTCDate(start.getUTCDate()+6);}else if(kind==='mes'){start.setUTCDate(1);end=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0,12));}else if(kind!=='dia')throw Error('Período inválido');const days=[];for(let cursor=new Date(start);cursor<=end;cursor.setUTCDate(cursor.getUTCDate()+1))days.push(cursor.toISOString().slice(0,10));return days;}
